# -*- coding: utf-8 -*-
"""Controles del Anexo A (ISO/IEC 27001:2022) relacionados con «Gestión de Operaciones TI». Parte 2: A.5.29 a A.8.32."""

CONTROLES_2 = [
{'id':'A.5.29','nombre':'Seguridad de la información durante una interrupción','en':'Information security during disruption','rol':'cronograma','prio':1,
 'exige':'La empresa debe planificar cómo mantener la seguridad de la información en un nivel adecuado cuando ocurre una interrupción grave (falla de sistemas, ciberataque, desastre, caída de un proveedor). No basta con volver a operar: durante la emergencia no deben abandonarse las protecciones (por ejemplo, no se deben compartir contraseñas «para salir del paso»).',
 'importa':'Las emergencias son el momento en que más se improvisa y más se relaja la seguridad. Los atacantes lo saben y aprovechan los desastres para entrar.',
 'preguntas':[
  ('¿Existe un [[BCP]]? Muéstremelo: ¿quién lo aprobó, en qué fecha y cuándo se revisó por última vez?','Debe estar vigente (revisado en el último año), aprobado por la dirección y con versión. Anote código, versión y fecha.'),
  ('En ese plan, ¿dónde se indica qué protecciones de seguridad se mantienen durante la emergencia (accesos, cifrado, registros) y cuáles se pueden relajar con autorización?','Debe haber una sección o apartado que lo diga. Si el plan solo habla de «volver a operar» y no de seguridad, el control no se cumple.'),
  ('¿Qué servicios y procesos están cubiertos y con qué criterio se escogieron? ¿Existe un [[BIA]]?','Debe existir el estudio de impacto que justifique el orden de prioridad de los servicios.'),
  ('¿Quién decide activar el plan, cómo se avisa a todos y dónde están los contactos de emergencia? ¿Están actualizados?','Debe haber un responsable, un árbol de llamadas o equivalente y teléfonos recientes. Pruebe llamando a un contacto en vivo.'),
  ('¿Se ha activado el plan alguna vez, en un caso real o en un simulacro? ¿Qué se aprendió y qué se corrigió?','Debe haber un registro con fecha y acciones de mejora. Un plan que nunca se ha probado no es confiable.')],
 'evidencias':['Plan de continuidad del negocio (BCP) vigente, con versión, fecha y aprobación de la dirección','Análisis de impacto al negocio (BIA) con la lista de servicios críticos','Sección del plan que describa los controles de seguridad que se mantienen en contingencia','Lista de contactos de crisis con fecha de actualización','Acta de la última prueba o simulacro, o del último uso real, con lecciones y acciones'],
 'prueba':'Abra el plan y busque las palabras «seguridad», «acceso» y «contraseña». Si ninguna aparece en el contexto de la emergencia, el plan no contempla la seguridad. Luego pida llamar en vivo a un contacto de la lista: si el número no sirve, la lista está desactualizada.',
 'alertas':['El plan ignora la seguridad (ejemplo: «en emergencia se comparten las contraseñas del administrador»)','Plan sin fecha, sin versión o sin aprobación','Contactos desactualizados','Nunca se ha probado','El plan existe pero el personal operativo no sabe dónde está'],
 'nc':'No existe plan de continuidad que contemple la seguridad de la información, o el plan existe pero no es conocido ni se mantiene vigente. (Observación si existe y se cumple pero hay aspectos mejorables, por ejemplo falta documentar qué controles se relajan.)'},

{'id':'A.5.30','nombre':'Preparación de las TIC para la continuidad del negocio','en':'ICT readiness for business continuity','rol':'cronograma','prio':1,
 'exige':'Las [[TIC]] (sistemas, redes, programas y servicios) deben estar preparadas para la continuidad: planificadas, implementadas, mantenidas y PROBADAS con base en los objetivos de continuidad del negocio y en los requisitos de continuidad de las TIC. En concreto: tener definidos el [[RTO]] y el [[RPO]] de cada servicio crítico, y demostrar con pruebas que se pueden cumplir.',
 'importa':'Es el punto en que se comprueba si la promesa de recuperación es real. Un plan puede decir «recuperamos en 4 horas» pero si nunca se ha probado, nadie sabe si son 4 horas, 4 días o nunca.',
 'preguntas':[
  ('Para cada servicio crítico, ¿cuál es el objetivo de tiempo de recuperación y cuál el objetivo de punto de recuperación? Muéstreme la tabla donde están definidos.','Debe haber una tabla con un valor por servicio, aprobada por la dirección o el dueño del servicio. Anote los valores de dos servicios.'),
  ('¿Cuándo fue la última prueba de recuperación? ¿Qué servicio se recuperó, cuánto tardó realmente y cuánta información se perdió?','Debe haber un informe con fecha (idealmente del último año) y tiempos reales. Compare el tiempo real con el RTO y la pérdida real con el RPO.'),
  ('Si la prueba no cumplió el tiempo o la pérdida prometida, ¿qué se corrigió y se volvió a probar?','Debe haber un plan de acciones con cierre y, ojalá, una segunda prueba.'),
  ('¿Qué infraestructura soporta esa recuperación (sitio alterno, copias de seguridad fuera del sitio, nube)? ¿Está contratada y vigente?','Debe haber contratos o evidencia de que el sitio alterno o el servicio de respaldo existe y está activo.'),
  ('¿Quién ejecutaría la recuperación y está capacitado? ¿Qué pasa si esa persona no está?','Debe haber roles, un suplente y evidencia de entrenamiento.')],
 'evidencias':['Tabla de RTO y RPO por servicio crítico, aprobada','Informe de la última prueba de recuperación con fecha, alcance, participantes, tiempos reales y resultado','Plan de acciones correctivas de la prueba y evidencia de su cierre','Calendario anual de pruebas de continuidad y recuperación','Contrato o evidencia del sitio alterno o servicio de recuperación','Reportes de ejecución de las copias de seguridad que sustentan el RPO declarado'],
 'prueba':'En el informe de la última prueba, anote el tiempo real y el tiempo prometido y compárelos usted mismo. Si el real es mayor al prometido y no hay acción registrada, tiene un hallazgo.',
 'alertas':['No hay RTO ni RPO definidos','Nunca se ha hecho una prueba de recuperación','La prueba fue hace más de un año','El tiempo real supera al prometido y nadie lo corrigió','Copia de seguridad guardada en el mismo lugar que el servidor','Solo una persona sabe recuperar'],
 'nc':'No hay objetivos de recuperación definidos para los servicios críticos, o nunca se ha probado la recuperación. (Si el incumplimiento es general en todos los servicios críticos, aplique los criterios de MAYOR de la empresa: falla sistemática y alto riesgo para el servicio.)'},

{'id':'A.5.37','nombre':'Procedimientos operativos documentados','en':'Documented operating procedures','rol':'relacionado','prio':2,
 'exige':'Los procedimientos de operación de las instalaciones de procesamiento de información (por ejemplo, cómo se hace una copia de seguridad, cómo se da de alta a un usuario, cómo se despliega un servicio) deben estar documentados y al alcance de quien los necesita.',
 'importa':'Si todo está «en la cabeza» de una persona, la empresa depende de ella: si falta o se va, el servicio queda en riesgo.',
 'preguntas':[
  ('¿Qué tareas críticas de operación tienen procedimiento escrito (copias de seguridad, altas y bajas de usuarios, despliegues, reinicios, atención de fallas)?','Debe haber una lista y los documentos. Las tareas críticas sin procedimiento son una brecha.'),
  ('Muéstreme dos de esos procedimientos: ¿quién los aprobó, de cuándo son y dónde los encuentra el operador?','Cada uno debe tener versión, fecha y aprobador, y encontrarse con facilidad.'),
  ('Pida a un operador que me explique o ejecute uno de ellos sin ayuda de su autor.','Si no puede hacerlo, el documento no es útil o no se usa.')],
 'evidencias':['Lista de procedimientos operativos','Dos procedimientos con versión, fecha de aprobación y aprobador','Registros recientes de ejecución de esos procedimientos'],
 'prueba':'Pida que el operador ejecute (o explique con el documento en la mano) un procedimiento. Observe si lo sigue paso a paso o lo hace de memoria.',
 'alertas':['Procedimientos sin aprobar o de hace años','Se trabaja distinto a lo escrito','Un solo empleado conoce la tarea','Procedimientos que nadie encuentra'],
 'nc':'Tareas críticas de operación no tienen ningún procedimiento documentado, o el existente no se sigue.'},

{'id':'A.6.8','nombre':'Notificación de eventos de seguridad de la información','en':'Information security event reporting','rol':'relacionado','prio':2,
 'exige':'La empresa debe dar a su personal un mecanismo para reportar rápidamente los [[evento]]s de seguridad que observen o sospechen (correo sospechoso, equipo perdido, comportamiento raro de un sistema), por canales adecuados y a tiempo.',
 'importa':'Los empleados son la primera línea de detección. Si no saben a quién avisar o temen represalias, los incidentes se descubren tarde.',
 'preguntas':[
  ('¿Cómo reporta un empleado un evento de seguridad (un correo sospechoso, un equipo perdido)? ¿Dónde está indicado el canal?','Debe haber un canal claro (correo, teléfono, formulario) y conocido por el personal.'),
  ('Pregunte a dos personas del equipo qué harían si encuentran un equipo extraño conectado a la red.','Ambas deberían nombrar el mismo canal. Si cada una dice algo distinto, el mecanismo no se conoce.'),
  ('¿Cuántos reportes de empleados se recibieron en el último año y qué se hizo con ellos?','Debe haber registros. Cero reportes en un año también es una señal de alerta: puede indicar que no se reporta.')],
 'evidencias':['Procedimiento y canal de reporte','Registro de reportes recibidos con su atención','Evidencia de comunicación del canal al personal (inducción, intranet, cartel)'],
 'prueba':'Pregunte en el área, sin preparar, a dos empleados distintos qué hacen y a quién avisan.',
 'alertas':['Canales informales no registrados','Nadie sabe a quién reportar','Reportes sin respuesta','Cero reportes en el último año'],
 'nc':'No existe canal de reporte, o existe pero el personal lo desconoce de manera generalizada.'},

{'id':'A.8.6','nombre':'Gestión de la capacidad','en':'Capacity management','rol':'relacionado','prio':2,
 'exige':'El uso de los recursos de los sistemas ([[capacidad]]) debe vigilarse y ajustarse según las necesidades actuales y las proyectadas. Es decir, la empresa debe saber cuánto espacio, potencia y ancho de banda usa y anticipar cuándo se agotará, antes de que ocurra.',
 'importa':'Cuando el espacio de un servidor se llena, el servicio se cae. Es una falla evitable con vigilancia y planificación.',
 'preguntas':[
  ('¿Cómo vigilan el uso de espacio, procesamiento y ancho de banda de los sistemas críticos? ¿Quién lo revisa y con qué frecuencia?','Debe haber una herramienta o un informe periódico con responsable.'),
  ('¿A qué porcentaje de uso se activa una alerta (umbral) y qué se hace cuando se activa?','Debe haber [[umbral]]es definidos y casos registrados de acción.'),
  ('¿Cómo proyectan el crecimiento de los próximos 12 meses y cómo se refleja en el presupuesto?','Debe existir una proyección y evidencia de que se tradujo en una compra o ampliación planificada.'),
  ('Muéstreme el último caso en que se tuvo que ampliar la capacidad: ¿se hizo antes de que hubiera problemas o después?','Una ampliación planificada es buena señal; una reactiva (después de una caída) indica que el control no funciona.')],
 'evidencias':['Informes de capacidad de los últimos meses','Configuración de umbrales de alerta','Proyección de crecimiento o plan de capacidad','Registro de la última ampliación con su motivo'],
 'prueba':'Pida ver el espacio libre actual de un servidor crítico en pantalla y compárelo con el umbral de alerta definido.',
 'alertas':['Sin vigilancia: se reacciona cuando el disco se llena','Caídas pasadas por falta de capacidad','Umbrales no configurados','Sin presupuesto para crecimiento'],
 'nc':'No existe ningún mecanismo de vigilancia ni planificación de capacidad de los sistemas críticos.'},

{'id':'A.8.9','nombre':'Gestión de la configuración','en':'Configuration management','rol':'relacionado','prio':2,
 'exige':'Las configuraciones (incluidas las de seguridad) de equipos, programas, servicios y redes deben establecerse, documentarse, implementarse, vigilarse y revisarse. Es decir, debe existir una configuración estándar segura ([[linea_base]]) y la empresa debe poder detectar cuándo algo se desvía de ella.',
 'importa':'Un servidor configurado a mano, sin registro, puede quedar con una protección desactivada y nadie lo nota. Muchos ataques aprovechan configuraciones inseguras.',
 'preguntas':[
  ('¿Existe una configuración estándar segura para servidores, equipos y redes? Muéstreme el documento y dígame cuándo se revisó.','Debe haber un documento con fecha y revisión reciente.'),
  ('¿Dónde se registra la configuración real de cada equipo o servicio (por ejemplo, una [[CMDB]])?','Debe haber un registro central y actualizado.'),
  ('¿Cómo detectan que un equipo se desvió de la configuración estándar? Muéstreme un caso.','Debe haber una herramienta o revisión periódica y un ejemplo de desviación detectada y corregida.'),
  ('Elijamos un servidor y comparemos su configuración real contra la estándar.','Una diferencia sin explicación es un hallazgo potencial.')],
 'evidencias':['Documento de configuración estándar segura con fecha de revisión','Registro de la configuración de los equipos críticos (CMDB o equivalente)','Informe de desviaciones detectadas y su corrección'],
 'prueba':'Pida que un técnico le muestre en pantalla la configuración de un servidor y compárela con el documento estándar punto por punto (aunque no entienda los términos, verifique que cada ítem del documento aparece igual).',
 'alertas':['No existe configuración estándar','Cada servidor está configurado distinto sin registro','Nadie detecta cambios no autorizados','Registro de configuración desactualizado'],
 'nc':'No existe configuración estándar documentada ni registro de la configuración de los activos críticos.'},

{'id':'A.8.13','nombre':'Copia de seguridad de la información','en':'Information backup','rol':'relacionado','prio':2,
 'exige':'Deben mantenerse [[backup]]s de la información, el software y los sistemas, y deben PROBARSE regularmente de acuerdo con la política acordada. Una copia que nunca se ha restaurado no es una garantía.',
 'importa':'Es la última defensa ante un ataque de [[ransomware]], un error humano o una falla de equipo. Si falla la copia, la información se pierde. Este control ya se revisa con más detalle en la sesión de Tecnología; hoy solo se cruza con la continuidad del servicio.',
 'preguntas':[
  ('Para los servicios críticos, ¿qué se respalda, con qué frecuencia y dónde se guarda la copia? ¿Esa frecuencia permite cumplir el objetivo de punto de recuperación?','La frecuencia de la copia debe ser igual o más frecuente que el RPO. Si el RPO es 1 hora y la copia es diaria, no se cumple.'),
  ('¿Cuándo fue la última prueba de restauración de un servicio crítico y qué resultado tuvo?','Debe haber un registro con fecha, qué se restauró, cuánto tardó y si funcionó.'),
  ('¿Está la copia protegida contra el borrado o el cifrado por un atacante (aislada, inmutable o fuera de la red)?','Debe haber una copia que un atacante con acceso a la red no pueda borrar.')],
 'evidencias':['Reportes de ejecución de copias de los últimos 30 días','Registro de la última prueba de restauración','Evidencia de la copia fuera del sitio o aislada'],
 'prueba':'Pida la restauración de un archivo elegido por usted y observe cuánto tarda y que funciona.',
 'alertas':['Copias fallidas sin seguimiento','Nunca se ha probado una restauración','La copia está en el mismo servidor','La frecuencia de copia no cumple el RPO'],
 'nc':'No se realizan copias de seguridad de servicios críticos, o nunca se han probado.'},

{'id':'A.8.14','nombre':'Redundancia de las instalaciones de procesamiento de información','en':'Redundancy of information processing facilities','rol':'relacionado','prio':1,
 'exige':'Las instalaciones que procesan información deben tener redundancia (equipos o enlaces de respaldo) suficiente para cumplir los requisitos de disponibilidad: si algo falla, otro componente toma su lugar sin detener el servicio.',
 'importa':'Si el servicio se vendió con una promesa de disponibilidad alta en el [[SLA]], pero depende de un solo servidor o un solo enlace de internet, la promesa no se puede cumplir.',
 'preguntas':[
  ('¿Qué servicios críticos tienen redundancia (servidores, enlaces de internet, energía, almacenamiento) y cuáles no? ¿Dónde está documentado?','Debe haber un diagrama o lista que muestre claramente qué está duplicado.'),
  ('Compare con el SLA: ¿los servicios que prometen disponibilidad alta tienen la redundancia necesaria para cumplirla?','Si prometen 99,9 % de disponibilidad con un [[spof]], hay una incoherencia.'),
  ('¿Cuándo fue la última prueba de [[failover]] y qué resultado tuvo?','Debe haber un informe con fecha y resultado. La redundancia nunca probada no es confiable.'),
  ('¿Qué pasa si se va la luz o se cae el enlace principal de internet?','Debe haber un [[UPS]] o planta eléctrica y un segundo enlace de internet, con evidencia de prueba.')],
 'evidencias':['Diagrama de arquitectura con los componentes redundantes y los puntos únicos de falla','Informe de la última prueba de conmutación por falla','Contratos de enlaces y de energía de respaldo','Registro de mantenimiento del UPS o planta eléctrica'],
 'prueba':'Con el diagrama en la mano, señale un servicio crítico y pregunte: «si este equipo se apaga ahora, ¿qué pasa?». Debe poder explicar cuál otro lo reemplaza.',
 'alertas':['Un único punto de falla en un servicio con SLA alto','Redundancia nunca probada','Un solo enlace de internet','UPS sin mantenimiento'],
 'nc':'Servicios con compromiso de disponibilidad alto operan sin redundancia suficiente y sin justificación de riesgo aceptada formalmente.'},

{'id':'A.8.15','nombre':'Registro (logging)','en':'Logging','rol':'relacionado','prio':2,
 'exige':'Los [[log]]s que anotan las actividades, excepciones, fallas y otros eventos relevantes deben producirse, guardarse, protegerse y analizarse. Sin registros no hay forma de investigar un incidente ni de demostrar qué ocurrió.',
 'importa':'Es el equivalente a las cámaras de seguridad de un edificio: si no hay grabación (o si el intruso puede borrarla), no se puede saber qué pasó.',
 'preguntas':[
  ('¿Qué eventos registran los sistemas críticos (accesos, cambios de privilegios, acciones de administradores, fallas)? ¿Por cuánto tiempo se conservan?','Debe haber una definición escrita de qué se registra y por cuánto tiempo.'),
  ('¿Quién puede borrar o modificar los registros?','Los administradores no deberían poder borrar sus propios registros. Si pueden, es un riesgo.'),
  ('¿Quién revisa los registros y con qué frecuencia? Muéstreme la última revisión.','Debe haber un responsable y evidencia de revisión, o una herramienta de alertas automáticas.')],
 'evidencias':['Configuración o política de registros y retención','Muestra de registros reales de un sistema crítico del último mes','Evidencia de protección de los registros (envío a un servidor central, permisos)','Registro de revisión o alertas generadas'],
 'prueba':'Pida ver los registros de un día cualquiera del último mes de un sistema crítico y compruebe que existen y contienen fecha, hora y usuario.',
 'alertas':['Registros que se borran en pocos días','Administradores que pueden borrar sus registros','Registros que nadie revisa','Horas de los sistemas descuadradas'],
 'nc':'Los sistemas críticos no generan registros suficientes o los registros no están protegidos ni se revisan.'},

{'id':'A.8.16','nombre':'Actividades de seguimiento (monitoreo)','en':'Monitoring activities','rol':'cronograma','prio':1,
 'exige':'Las redes, sistemas y aplicaciones deben vigilarse para detectar comportamientos anómalos (accesos raros, uso extraño de recursos, intentos de ataque), y debe actuarse de manera adecuada para evaluar posibles [[incidente]]s. No basta con tener la herramienta: alguien debe mirar las alertas y reaccionar.',
 'importa':'Es el sistema de alarma de la empresa. Una alarma que nadie escucha, o que solo suena en horario laboral cuando el servicio se vende como 24 horas, no protege.',
 'preguntas':[
  ('¿Qué se vigila (servidores, red, aplicaciones, accesos) y con qué herramientas? Muéstreme el [[panel]] en vivo.','Pida verlo en pantalla, no en un informe. Debe mostrar el estado actual y alertas abiertas reales.'),
  ('De la lista de activos críticos, ¿cuántos están conectados al monitoreo?','Compare la lista del monitoreo con el inventario. Un activo crítico fuera del monitoreo es una brecha.'),
  ('¿Quién recibe y revisa las alertas, y qué ocurre fuera del horario laboral, en fines de semana y festivos?','Debe haber guardias o un [[SOC]]. Si el acuerdo de servicio promete atención 24/7 y no hay nadie fuera de horario, hay incumplimiento.'),
  ('Muéstreme tres alertas del último mes: ¿qué se hizo con cada una, quién y en cuánto tiempo?','Cada alerta debe tener un [[ticket]] o registro con tiempos. Alertas sin respuesta son una alerta para usted.'),
  ('¿Cómo se definieron los umbrales y cada cuánto se revisan? ¿Cómo se evita saturar con falsas alarmas?','Debe haber criterios y revisiones. Muchas falsas alarmas hacen que nadie atienda las reales.'),
  ('Cuando una alerta puede ser un ataque, ¿cómo se decide si es un incidente de seguridad?','Debe conectar con el procedimiento de evaluación de eventos (control A.5.25).')],
 'evidencias':['Panel de monitoreo mostrado en vivo con los sistemas cubiertos','Lista de elementos monitoreados cotejada contra el inventario de activos críticos','Alertas del último mes con su ticket, responsable y tiempo de respuesta','Esquema de guardias o turnos para atención fuera de horario','Procedimiento de revisión de alertas y umbrales definidos','Reporte periódico de monitoreo a la dirección o al responsable del servicio'],
 'prueba':'Elija usted tres alertas del listado del último mes y reconstruya el recorrido: hora de la alerta → hora de atención → hora de cierre. Compare el tiempo con el acuerdo de servicio.',
 'alertas':['Alertas que nadie atiende','Monitoreo solo en horario laboral con un compromiso 24/7','Activos críticos sin monitoreo','Umbrales nunca revisados','El panel no muestra datos actuales'],
 'nc':'No existe monitoreo de los sistemas críticos, o existe pero las alertas no se atienden. (Si las alertas sin atender son sistemáticas y afectan servicios con compromiso 24/7, aplique los criterios de MAYOR de la empresa.)'},

{'id':'A.8.32','nombre':'Gestión de cambios','en':'Change management','rol':'relacionado','prio':1,
 'exige':'Los cambios en las instalaciones de procesamiento de información y en los sistemas deben estar sujetos a procedimientos de gestión de cambios: cada cambio se pide, se evalúa por riesgo, se aprueba por alguien distinto del solicitante, se prueba, se planifica (incluyendo cómo volver atrás si sale mal) y se registra.',
 'importa':'Una gran parte de las caídas de servicio las provocan cambios mal hechos, sin aprobación o sin plan de vuelta atrás. Y un cambio sin registro hace imposible investigar qué ocurrió.',
 'preguntas':[
  ('¿Cómo se pide, aprueba y aplica un cambio en producción? Muéstreme el procedimiento.','Debe haber un procedimiento con roles definidos: solicitante, aprobador y ejecutor.'),
  ('Elijamos tres cambios del último trimestre que escoja yo: muéstreme el expediente ([[RFC]]) de cada uno.','Cada expediente debe tener: solicitud, evaluación de riesgo, aprobación, pruebas, plan de [[rollback]] y cierre. Anote qué le falta a cada uno.'),
  ('¿Quién aprueba los cambios y puede el solicitante aprobar su propio cambio?','El aprobador debe ser distinto del solicitante. Si coincide, hay un riesgo (falta de segregación de funciones).'),
  ('¿Cómo se manejan los cambios urgentes? ¿Se documentan después y quién los revisa?','Debe existir un procedimiento y los cambios urgentes deben aparecer con registro posterior.'),
  ('¿Existe un [[CAB]] que se reúna? Muéstreme las actas.','Si la empresa lo define, debe haber actas con fechas. Si no existe, pregunte quién cumple esa función.')],
 'evidencias':['Procedimiento de gestión de cambios','Tres expedientes de cambio elegidos por usted, completos','Registro de cambios urgentes y su revisión posterior','Calendario de ventanas de cambio y comunicaciones a los afectados','Actas del comité de cambios (si existe)'],
 'prueba':'Elija tres cambios con fecha distinta. Para cada uno verifique: ¿quién lo pidió? ¿quién lo aprobó? ¿hay evidencia de pruebas? ¿hay plan de reversión? Una casilla vacía por expediente es una desviación.',
 'alertas':['Cambios directos en producción sin registro','El solicitante se aprueba a sí mismo','Cambios urgentes sin revisión posterior','Expedientes sin plan de reversión','Cambios sin comunicar a los afectados'],
 'nc':'Existen cambios en producción sin aprobación ni registro, de forma repetida en la muestra. (Si solo falta un dato en un expediente aislado, probablemente es una No conformidad MENOR u observación; decida según los criterios de la empresa.)'},
]
